const root=document.querySelector('#app');
const pages={beranda:'Beranda',mengenal:'Mengenal SB',kamus:'Kamus Biaya',regulasi:'Regulasi',dashboard:'Dashboard',pustaka:'Pustaka',faq:'FAQ'};
const icon=(name,size=20)=>{const paths={search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',book:'<path d="M4 19V5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0 0 4h13"/>',shield:'<path d="m12 2 8 4v6c0 5-3 8-8 10-5-2-8-5-8-10V6l8-4Z"/><path d="m9 12 2 2 4-4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h4m6-4 4-4-4-4m-9 4h13"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8L3 5Z"/>',chart:'<path d="M3 3v18h18M7 16l4-4 4 2 5-7"/>',file:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 13h7m-7 4h7"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 3h.01"/>'};return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.book}</svg>`;};
// Regulasi pilihan: data referensi disajikan tanpa bergantung pada publikasi D1.
// Data besaran per item tetap harus disinkronkan melalui Google Sheets resmi.
const FEATURED_REGULATIONS = [
 {id:'REF-PMK-54-2026',kelompok:'SBM 2027',jenis:'PMK',nomor:'54',tahun:2026,judul:'Standar Biaya Masukan',deskripsi:'Kerangka SBM dalam penyusunan rincian biaya keluaran; rincian angka mengikuti ketentuan pelaksanaan yang berlaku.',url:'https://jdih.kemenkeu.go.id/dok/pmk-54-tahun-2026',status_verifikasi:'Terverifikasi JDIH',sumber:'JDIH Kementerian Keuangan'},
 {id:'REF-KMK-296-2026',kelompok:'SBM 2027',jenis:'KMK',nomor:'296',tahun:2026,judul:'Rincian Besaran Biaya Masukan Tahun Anggaran 2027',deskripsi:'Referensi rincian besaran SBM TA 2027. Periksa naskah lengkap dan lampiran sebelum menggunakan angka satuan biaya.',url:'https://perencanaan.uin-malang.ac.id/ar/kmk-296-tahun-2026-tentang-rincian-besaran-biaya-masukan-tahun-anggaran-2027/',status_verifikasi:'Referensi sekunder — cek naskah asli',sumber:'Perencanaan UIN Malang'},
 {id:'REF-PMK-79-2025',kelompok:'SSB',jenis:'PMK',nomor:'79',tahun:2025,judul:'Standar Struktur Biaya dalam Penganggaran Kementerian Negara/Lembaga',deskripsi:'Mengatur komposisi biaya utama dan biaya pendukung dalam suatu keluaran.',url:'https://jdih.kemenkeu.go.id/dok/pmk-79-tahun-2025',status_verifikasi:'Terverifikasi JDIH',sumber:'JDIH Kementerian Keuangan'},
 {id:'REF-PMK-3-2026',kelompok:'SBK 2027',jenis:'PMK',nomor:'3',tahun:2026,judul:'Standar Biaya Keluaran dalam Penganggaran Kementerian Negara/Lembaga',deskripsi:'Kerangka Standar Biaya Keluaran umum dan khusus dalam penganggaran kementerian/lembaga.',url:'https://jdih.kemenkeu.go.id/dok/pmk-3-tahun-2026',status_verifikasi:'Terverifikasi JDIH',sumber:'JDIH Kementerian Keuangan'},
 {id:'REF-KMK-57-2026',kelompok:'SBK 2027',jenis:'KMK',nomor:'57',tahun:2026,judul:'KMK 57 Tahun 2026 — referensi SBK 2027 (perlu verifikasi)',deskripsi:'Nomor diberikan oleh pengelola portal. Judul lengkap, kesesuaian substansi, dan naskah resmi masih perlu diverifikasi sebelum dipakai sebagai dasar hukum.',url:'',status_verifikasi:'Belum terverifikasi — jangan gunakan sebagai dasar penetapan',sumber:'Usulan pengelola portal'}
];
const verifiedLink=(url)=>typeof url==='string' && /^https:\/\//.test(url);
const state={page:'beranda',search:'',jenis:'',data:[],summary:null,regs:[],docs:[],faq:[],loading:true,error:'',selected:null};
const escapeHTML=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const niceDate=(d)=>{if(!d)return '—';const x=new Date(d);return isNaN(x)?String(d):new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(x)};
const badge=(s)=>`<span class="pill">${escapeHTML(s)}</span>`;
async function load(){state.loading=true;render();try{const endpoints=['summary','items?limit=500','regulations?limit=500','documents?limit=500','faq?limit=500'];const responses=await Promise.all(endpoints.map(x=>fetch('/api/'+x,{credentials:'same-origin',cache:'no-store'})));if(responses.some(x=>x.status===401)){location.href='/login';return;}if(responses.some(x=>!x.ok))throw Error('Gagal membaca data portal');const [summary,items,regs,docs,faq]=await Promise.all(responses.map(x=>x.json()));state.summary=summary.data||null;state.data=items.data||[];state.regs=regs.data||[];state.docs=docs.data||[];state.faq=faq.data||[];state.error='';}catch(e){state.error=e.message||'Tidak dapat memuat data. Coba muat ulang halaman.';}state.loading=false;render();}
const menu=()=>Object.entries(pages).map(([id,label])=>`<button class="nav-link ${state.page===id?'active':''}" data-page="${id}">${label}</button>`).join('');
const stat=(value,title,ic)=>`<article class="stat"><span class="stat-icon">${icon(ic,22)}</span><div><strong>${escapeHTML(value)}</strong><small>${title}</small></div></article>`;
const typeCards=()=>[['SBM','Standar Biaya Masukan','Acuan biaya komponen masukan dan pelaksanaan kegiatan.','sbm.svg'],['SBK','Standar Biaya Keluaran','Pendekatan biaya per keluaran atau hasil kegiatan.','sbk.svg'],['SSB','Standar Struktur Biaya','Informasi struktur dan komposisi biaya.','ssb.svg']].map(([k,t,desc,img])=>`<article class="type-card"><img src="/icons/${img}" alt="Ikon ${k}"/><span>${k}</span><h3>${t}</h3><p>${desc}</p><button class="text-button" data-kind="${k}">Lihat item ${icon('arrow',16)}</button></article>`).join('');
const home=()=>`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> PUSAT INFORMASI STANDAR BIAYA</div><h1>Memahami Standar Biaya,<br><em>Lebih Mudah.</em></h1><p>Temukan definisi, jenis, item, besaran, regulasi, dan referensi standar biaya dalam satu portal yang terstruktur.</p><form id="hero-search" class="search-box">${icon('search',21)}<input name="q" placeholder="Cari honorarium, perjalanan dinas, SBM, regulasi..." aria-label="Cari standar biaya"/><button type="submit">Cari Sekarang ${icon('arrow',17)}</button></form><div class="quick">Penelusuran cepat: <button data-search="Honorarium">Honorarium</button><button data-search="Perjalanan Dinas">Perjalanan Dinas</button><button data-kind="SBK">Standar Biaya Keluaran</button></div></div><div class="hero-art" aria-hidden="true"><div class="halo"></div><img class="hero-core" src="/icons/portal-logo.svg"/><img class="orbit a" src="/icons/sbm.svg"/><img class="orbit b" src="/icons/sbk.svg"/><img class="orbit c" src="/icons/ssb.svg"/><div class="art-label">STANDAR<br>BIAYA</div></div></section><section class="stats">${stat(state.summary?.itemCount??'—','Item Standar Biaya','book')}${stat(state.summary?.regulationCount??'—','Referensi Regulasi','file')}${stat(state.summary?.documentCount??'—','Dokumen Pustaka','shield')}${stat(niceDate(state.summary?.updatedAt),'Terakhir Diperbarui','calendar')}</section><section class="section-heading"><div><span class="small-label">JELAJAHI KATALOG</span><h2>Jenis Standar Biaya</h2><p>Pilih kategori untuk mulai menjelajahi referensi dan ketentuannya.</p></div><button class="secondary" data-page="kamus">Buka Kamus ${icon('arrow',17)}</button></section><section class="types">${typeCards()}</section>`;
const cards=(items,kind)=>items.map(x=>`<article class="entry"><div class="entry-head">${badge(x.jenis||x.kategori||x.status||kind)}<small>${escapeHTML(x.tahun||x.nomor||'')}</small></div><h3>${escapeHTML(x.nama||x.judul||x.pertanyaan||'Tidak ada judul')}</h3><p>${escapeHTML(x.definisi||x.deskripsi||x.jawaban||x.kelompok||'')}</p><div class="entry-foot">${x.satuan?`<span>Satuan: ${escapeHTML(x.satuan)}</span>`:''}${x.id&&kind==='Item'?`<button class="text-button" data-detail="${escapeHTML(x.id)}">Detail ${icon('arrow',15)}</button>`:''}${x.url&&/^https:\/\//.test(x.url)?`<a href="${escapeHTML(x.url)}" target="_blank" rel="noopener noreferrer">Lihat regulasi ↗</a>`:''}</div></article>`).join('');
const filtered=()=>state.data.filter(x=>(!state.jenis||x.jenis===state.jenis)&&(!state.search||JSON.stringify([x.nama,x.kelompok,x.subkelompok,x.definisi,x.jenis]).toLowerCase().includes(state.search.toLowerCase())));
const catalog=()=>`<section class="page-head"><span class="small-label">KAMUS STANDAR BIAYA</span><h1>Jelajahi Kamus Biaya</h1><p>Penelusuran item yang telah tersedia dalam database portal.</p></section><div class="toolbar"><label class="filter-search">${icon('search',20)}<input id="catalog-search" placeholder="Cari nama, kelompok, definisi..." value="${escapeHTML(state.search)}" /></label><label class="kind-select">${icon('filter',18)}<select id="catalog-kind"><option value="">Semua jenis</option>${['SBM','SBK','SSB'].map(t=>`<option value="${t}" ${state.jenis===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="result-note">Menampilkan ${filtered().length} item dari katalog yang dimuat.</div><div class="entries">${filtered().length?cards(filtered(),'Item'):'<div class="empty">Belum ada item yang cocok dengan pencarian.</div>'}</div>${state.data.length>=500?'<p class="result-note">Katalog awal dibatasi 500 item. Gunakan pencarian server-side untuk katalog yang lebih besar.</p>':''}`;
const simple=(key,title,subtitle,items)=>`<section class="page-head"><span class="small-label">PORTAL STANDAR BIAYA</span><h1>${title}</h1><p>${subtitle}</p></section><div class="entries">${items.length?cards(items,key):'<div class="empty">Belum ada data yang dipublikasikan untuk bagian ini.</div>'}</div>`;
const regulationCatalog=()=>{
  const groups=['SBM 2027','SSB','SBK 2027'];
  const database=state.regs.filter(x=>!FEATURED_REGULATIONS.some(r=>String(r.jenis).toUpperCase()===String(x.jenis).toUpperCase()&&String(r.nomor)===String(x.nomor)&&Number(r.tahun)===Number(x.tahun)));
  const featured=groups.map(group=>`<section class="reg-group"><div class="reg-group-title"><h2>${escapeHTML(group)}</h2><span>${FEATURED_REGULATIONS.filter(x=>x.kelompok===group).length} referensi</span></div><div class="entries">${FEATURED_REGULATIONS.filter(x=>x.kelompok===group).map(r=>`<article class="entry regulation-entry"><div class="entry-head">${badge(r.jenis+' '+r.nomor+'/'+r.tahun)}<span class="verification ${r.status_verifikasi.startsWith('Terverifikasi')?'verified':'pending'}">${escapeHTML(r.status_verifikasi)}</span></div><h3>${escapeHTML(r.judul)}</h3><p>${escapeHTML(r.deskripsi)}</p><div class="entry-foot"><span>${escapeHTML(r.sumber)}</span>${verifiedLink(r.url)?`<a target="_blank" rel="noopener noreferrer" href="${escapeHTML(r.url)}">Lihat sumber ↗</a>`:'<span>Dokumen resmi belum tersedia</span>'}</div></article>`).join('')}</div></section>`).join('');
  return `<section class="page-head"><span class="small-label">DASAR HUKUM STANDAR BIAYA</span><h1>Regulasi SBM, SBK & SSB</h1><p>Regulasi pilihan tahun anggaran 2027, lengkap dengan tautan sumber dan status verifikasi dokumen.</p></section><div class="reg-advisory">Perhatian: tiga PMK di bawah telah dicocokkan dengan JDIH Kemenkeu. Referensi KMK 296/2026 masih menggunakan sumber sekunder, sedangkan KMK 57/2026 perlu naskah resmi. Besaran biaya belum otomatis dimuat dari lampiran.</div>${featured}${database.length?`<section class="reg-group"><div class="reg-group-title"><h2>Regulasi dari Database</h2><span>${database.length} dokumen</span></div><div class="entries">${cards(database,'Regulasi')}</div></section>`:''}`;
};
const faq=()=>`<section class="page-head"><span class="small-label">PUSAT BANTUAN</span><h1>Pertanyaan yang Sering Diajukan</h1><p>Jawaban ringkas mengenai standar biaya dan penggunaan portal.</p></section><section class="faqs">${state.faq.length?state.faq.map((x,i)=>`<details ${i===0?'open':''}><summary>${escapeHTML(x.pertanyaan)}</summary><p>${escapeHTML(x.jawaban)}</p></details>`).join(''):'<div class="empty">Belum ada FAQ yang dipublikasikan.</div>'}</section>`;
const intro=()=>`<section class="page-head"><span class="small-label">PENGENALAN</span><h1>Mengenal Standar Biaya</h1><p>Memahami ruang lingkup, jenis, dan peran standar biaya dalam perencanaan anggaran.</p></section><section class="types">${typeCards()}</section><section class="info-block"><h2>Referensi dalam satu tempat</h2><p>Portal ini menyajikan data standar biaya berdasarkan informasi yang tersedia dalam database. Selalu perhatikan tahun anggaran, satuan, wilayah, ketentuan dan regulasi yang berlaku sebelum menggunakan suatu besaran.</p></section>`;
const dashboard=()=>`<section class="page-head"><span class="small-label">RINGKASAN INFORMASI</span><h1>Dashboard Standar Biaya</h1><p>Ringkasan data yang tersedia pada publikasi terakhir.</p></section><section class="stats inpage">${stat(state.summary?.itemCount??'—','Total Item','book')}${stat(state.summary?.regulationCount??'—','Total Regulasi','file')}${stat(state.summary?.documentCount??'—','Total Dokumen','shield')}</section><section class="chart-panel"><h2>Distribusi Jenis Standar Biaya</h2>${(state.summary?.byType||[]).length?(state.summary.byType.map(x=>`<div class="bar-row"><span>${escapeHTML(x.name)}</span><div class="bar-track"><div style="width:${Math.round(100*Number(x.value)/(Math.max(1,...state.summary.byType.map(i=>Number(i.value)||0))))}%"></div></div><strong>${escapeHTML(x.value)}</strong></div>`).join('')):'<p>Belum ada ringkasan distribusi yang dipublikasikan.</p>'}</section>`;
const content=()=>state.page==='beranda'?home():state.page==='mengenal'?intro():state.page==='kamus'?catalog():state.page==='regulasi'?regulationCatalog():state.page==='dashboard'?dashboard():state.page==='pustaka'?simple('Dokumen','Pustaka Standar Biaya','Dokumen referensi yang telah disetujui untuk dipublikasikan.',state.docs):faq();
function render(){root.innerHTML=`<header class="topbar"><div class="container header-wrap"><button class="brand" data-page="beranda"><img src="/icons/portal-logo.svg" alt="Logo ilustratif portal"/><span><b>PORTAL STANDAR BIAYA</b><small>Pusat Informasi & Kamus Standar Biaya</small></span></button><nav id="nav">${menu()}</nav><div class="header-actions"><form action="/logout" method="post" id="logout-form"><button class="logout" type="submit">${icon('logout',17)}<span>Keluar</span></button></form><button id="mobile-menu" aria-label="Buka menu">${icon('menu',24)}</button></div></div></header><main class="container">${state.error?`<div class="error-box">${escapeHTML(state.error)} <button id="reload">Coba lagi</button></div>`:''}${state.loading?'<div class="loading">Memuat informasi portal...</div>':content()}</main><footer class="footer"><div class="container foot-inner"><div><b>PORTAL STANDAR BIAYA</b><p>Informasi terstruktur untuk penelusuran standar biaya.</p></div><span>Ilustrasi ikon khusus portal • Periksa dasar hukum sebelum penggunaan.</span></div></footer>`;bind();}
function go(page){state.page=page;state.selected=null;window.scrollTo({top:0,behavior:'smooth'});render();}
async function detail(id){const res=await fetch('/api/items/'+encodeURIComponent(id));if(!res.ok)return;const x=(await res.json()).data;const element=document.createElement('dialog');element.className='detail-dialog';element.innerHTML=`<button class="close-dialog" aria-label="Tutup">×</button>${badge(x.item?.jenis||'Item')}<h2>${escapeHTML(x.item?.nama)}</h2><p>${escapeHTML(x.item?.definisi||'')}</p><p><strong>Kelompok:</strong> ${escapeHTML(x.item?.kelompok)} &nbsp; <strong>Satuan:</strong> ${escapeHTML(x.item?.satuan)}</p><h3>Besaran Biaya</h3>${(x.rates||[]).length?'<div class="rate-list">'+x.rates.map(r=>`<p><b>${escapeHTML(r.tahun)}</b> · ${escapeHTML(r.wilayah)} · ${escapeHTML(r.kategori)}<br><strong>${r.mata_uang==='IDR'?'Rp ':''}${Number(r.besaran).toLocaleString('id-ID')}${r.mata_uang==='PCT'?'%':''}</strong></p>`).join('')+'</div>':'<p>Besaran tidak tersedia.</p>'}<h3>Referensi regulasi: ${(x.regulations||[]).length}</h3>`;document.body.append(element);element.showModal();element.querySelector('.close-dialog').onclick=()=>{element.close();element.remove();};element.onclick=e=>{if(e.target===element){element.close();element.remove();}};}
function bind(){document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>go(x.dataset.page));document.querySelectorAll('[data-search]').forEach(x=>x.onclick=()=>{state.search=x.dataset.search;state.jenis='';go('kamus');});document.querySelectorAll('[data-kind]').forEach(x=>x.onclick=()=>{state.jenis=x.dataset.kind;state.search='';go('kamus');});document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>detail(x.dataset.detail));document.querySelector('#hero-search')?.addEventListener('submit',e=>{e.preventDefault();state.search=new FormData(e.target).get('q')?.toString()||'';state.jenis='';go('kamus');});document.querySelector('#catalog-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;state.search=e.target.value;render();const node=document.querySelector('#catalog-search');node.focus();node.setSelectionRange(pos,pos);});document.querySelector('#catalog-kind')?.addEventListener('change',e=>{state.jenis=e.target.value;render();});document.querySelector('#mobile-menu')?.addEventListener('click',()=>document.querySelector('#nav').classList.toggle('open'));document.querySelector('#reload')?.addEventListener('click',load);}
load();
